Equilibrio y linealización del levitador (§12.2).
yb = 0.05;                                  % punto de operación [m]
[xs, us] = equilibrioLevitador(yb, P);
[A, B] = jacobianoLevitador(yb, P);
fprintf('equilibrio: x* = (%.3f, %g, %.4f),  u* = %.4f V\n', xs, us);
fprintf('valores propios de A: %s\n', mat2str(eig(A).', 5));
La promesa lineal contra la planta (§12.2).
Acl = A - B*K;  t = linspace(0, 0.6, 1201);
opc = odeset('RelTol', 1e-9, 'AbsTol', 1e-11, 'MaxStep', 1e-3);
y0s = [0.045 0.08 0.01 0.15];  Y = zeros(numel(t), 4);  YL = Y;
for j = 1:4
    x0 = [y0s(j); 0; xs(3)];
    [~, X] = ode45(@(t, x) modeloLevitador(x, us - K*(x - xs), P), t, x0, opc);
    U = us - (X - xs.')*K.';
    for i = 1:numel(t), d = expm(Acl*t(i))*(x0 - xs); YL(i, j) = d(1) + yb; end
    Y(:, j) = X(:, 1);
    fprintf('y0 = %.3f:  max|y - y_lin| = %.2e m,  max u = %5.2f V\n', y0s(j), max(abs(Y(:,j) - YL(:,j))), max(U));
end
Una carga que el modelo no conoce: control integral (§12.2).
mReal = @(t) 0.10 + 0.02*(t &gt;= 0.5);            % la carga que el modelo no conoce
opc = odeset('RelTol', 1e-9, 'AbsTol', 1e-11, 'MaxStep', 1e-3);
t = linspace(0, 3, 3001);
[~, X1] = ode45(@(t, x) modeloLevitador(x, us - K*(x - xs), P, mReal(t)), t, xs, opc);
lazo = @(t, z) [modeloLevitador(z(1:3), us - K1*(z(1:3) - xs) - K2*z(4), P, mReal(t)); z(1) - yb];
[~, Z2] = ode45(lazo, t, [xs; 0], opc);
U1 = us - (X1 - xs.')*K.';  U2 = us - (Z2(:,1:3) - xs.')*K1.' - K2*Z2(:,4);
fprintf('error final: estados = %.4f cm,  integral = %.1e m\n', 100*(X1(end,1) - yb), Z2(end,1) - yb);
fprintf('voltaje final con integrador = %.4f V;  R x3* con m = 0.12: %.4f V\n', U2(end), ...
        P.R*sqrt(2*P.g*0.12/(P.L0*P.a))*(P.a + yb));
El péndulo: cancelar contra aproximar (§12.3).
a = 10;  b = 1;  c = 10;  k1 = 4;  k2 = 3;  d = pi;       % a = g/l, b = k/m, c = 1/(m l^2)
uJac = @(x) (-(a + k1)*(x(1) - d) - k2*x(2))/c;
uExa = @(x) ( a*sin(x(1)) - k1*(x(1) - d) - k2*x(2))/c;
pend = @(u) @(t, x) [x(2); -a*sin(x(1)) - b*x(2) + c*u(x)];
opc = odeset('RelTol', 1e-11, 'AbsTol', 1e-12);  t = linspace(0, 6, 1201);
[~, XJ] = ode45(pend(uJac), t, [0; 0], opc);
[~, XE] = ode45(pend(uExa), t, [0; 0], opc);
[~, E]  = ode45(@(t, e) [e(2); -k1*e(1) - (b + k2)*e(2)], t, [-d; 0], opc);
pred = E(:, 1) + d;
fprintf('max|x1 - predicción|: exacta %.1e rad, jacobiana %.3f rad\n', ...
        max(abs(XE(:,1) - pred)), max(abs(XJ(:,1) - pred)));


Derivada de Lie: fórmula contra derivada medida (§12.4).
mu = 1;  f = @(x) [x(2); -x(1) + mu*(1 - x(1)^2)*x(2)];
lam = @(x) (x(1)^2 + x(2)^2)/2;
t = linspace(0, 16, 1601);  opc = odeset('RelTol', 1e-11, 'AbsTol', 1e-12);
[~, X] = ode45(@(t, x) f(x), t, [0.2; 0], opc);
L = mu*(1 - X(:,1).^2).*X(:,2).^2;                 % fórmula
lamt = 0.5*sum(X.^2, 2);  dlam = gradient(lamt, t(2) - t(1));   % derivada medida
Lnum = arrayfun(@(i) derivadaLie(f, lam, X(i,:).'), (1:numel(t)).');
fprintf('max|d lambda/dt - L_f lambda| = %.1e (diferencias en el tiempo)\n', max(abs(dlam(3:end-2) - L(3:end-2))));
fprintf('max|L_f lambda numérica - fórmula| = %.1e\n', max(abs(Lnum - L)));
Jacobiano no singular, función no inyectiva (§12.4).
Psi  = @(x) exp(x(1))*[cos(x(2)); sin(x(2))];
dPsi = @(x) exp(x(1))*[cos(x(2)) -sin(x(2)); sin(x(2)) cos(x(2))];
fprintf('det dPsi/dx en (0.3, 1) = %.4f = e^0.6 = %.4f\n', det(dPsi([0.3; 1])), exp(0.6));
fprintf('|Psi(0,0) - Psi(0,2 pi)| = %.1e: no es uno a uno\n', norm(Psi([0; 0]) - Psi([0; 2*pi])));
fprintf('Psi(-30, 0) = %.1e: Psi no es propia (x1 -&gt; -inf lleva a 0)\n', norm(Psi([-30; 0])));
Grado relativo: parámetros de Markov (§12.5).
% realizaciones en forma canónica controlable: (num, den) -&gt; (A, B, C)
G = {[1], [1 1]; [1], conv([1 1], [1 1]); [1], conv([1 1], conv([1 1], [1 1])); [1 2], conv([1 1], [1 3])};
tl = logspace(-4, -2, 20);  r = zeros(1, 4);  pend = r;
for j = 1:4
    num = G{j, 1};  den = G{j, 2};  n = numel(den) - 1;
    A = [zeros(n-1, 1) eye(n-1); -fliplr(den(2:end))];  B = [zeros(n-1, 1); 1];
    C = zeros(1, n);  C(1:numel(num)) = fliplr(num);
    k = 0;  while abs(C*A^k*B) &lt; 1e-12, k = k + 1; end;  r(j) = k + 1;
    escalon = @(t) sum(arrayfun(@(k) C*A^(k-1)*B*t^k/factorial(k), 1:25));  % y = sum C A^(k-1) B t^k/k!
    y = arrayfun(escalon, tl);
    p = polyfit(log(tl), log(abs(y)), 1);  pend(j) = p(1);
    fprintf('G%d: Markov C A^k B = %s  -&gt;  r = %d,  pendiente log-log = %.3f\n', j, ...
            mat2str(arrayfun(@(k) C*A^k*B, 0:n-1)), r(j), pend(j));
end
La forma normal es el mismo sistema (§12.6).
fx  = @(t, x) [-x(1); x(1)*x(2); x(2)] + [exp(x(2)); 1; 0]*u(t);
Phi = @(x) [x(3); x(2); 1 + x(1) - exp(x(2))];
% forma normal: x1 = -1 + z3 + e^z2 en las coordenadas nuevas
fz  = @(t, z) [ z(2);
                (-1 + z(3) + exp(z(2)))*z(2) + u(t);
               -(-1 + z(3) + exp(z(2)))*(1 + z(2)*exp(z(2))) ];
x0 = [0.3; -0.2; 0.5];
[~, X] = ode45(fx, t, x0, opc);  [~, Z] = ode45(fz, t, Phi(x0), opc);
PX = cell2mat(arrayfun(@(i) Phi(X(i,:).').', (1:numel(t)).', 'UniformOutput', false));
