u = @(t, x) (t &gt;= ton)*(x(1) - mu*(1 - x(1)^2)*x(2) - 4*x(1) - 4*x(2));
vdp = @(t, x) [x(2); -x(1) + mu*(1 - x(1)^2)*x(2) + u(t, x)];
