t1 = linspace(0, ton, 1001);  t2 = linspace(ton, 16, 601);
[~, X1] = ode45(vdp, t1, [0.5; 0], opc);                % libre
[~, X2] = ode45(vdp, t2, X1(end,:).', opc);             % con la ley
